function pay_invoice(p_invoice_id in number, p_amount in number) return varchar2 is
    e_overpayment exception;
    pragma exception_init(e_overpayment, -20010);
    v_open_amount number;
  begin
    v_open_amount := t008_invoice_pkg.get_open_amount(p_invoice_id); -- Assuming this function exists to check the condition
    if p_amount > v_open_amount then
      raise e_overpayment;
    end if;
    t008_invoice_pkg.apply_payment(p_invoice_id, p_amount);
    return 'PAID';
  exception
    when e_overpayment then
      return 'REJECTED';
  end pay_invoice;
end t008_payments_api;
/
